function drawFX(f){var a=point(f.x,f.y),b=point(f.tx,f.ty),v=1-f.life/(f.maxLife||.48),w=f.weapon||'plasma';if(f.muzzle){a.x+=f.muzzle.x*zoom;a.y+=f.muzzle.y*zoom;}else a.y-=15*zoom;b.y-=15*zoom;ctx.save();ctx.strokeStyle=f.color;ctx.fillStyle=f.color;ctx.lineWidth=2*zoom;if(w==='impact'){var radius=(f.radius||15)*zoom;ctx.globalAlpha=1-v;ctx.beginPath();ctx.arc(b.x,b.y+10,radius*v,0,Math.PI*2);ctx.stroke();for(var k=0;k<6;k++){var angle=k*1.047;box(b.x+Math.cos(angle)*radius*v,b.y+10+Math.sin(angle)*radius*v*.6-10*Math.sin(v*Math.PI),3*zoom,3*zoom,f.color);}}else if(w==='tesla'||w==='shock'){ctx.beginPath();ctx.moveTo(a.x,a.y);for(var k=1;k<=7;k++)ctx.lineTo(a.x+(b.x-a.x)*k/7+(k<7?Math.sin(k*12+frame)*7:0),a.y+(b.y-a.y)*k/7);ctx.stroke();}else if(w==='heal'||w==='sniper'){ctx.globalAlpha=1-v;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(w==='heal'){box(b.x-5,b.y-1,10,2,f.color);box(b.x-1,b.y-5,2,10,f.color);}}else{var t=Math.min(1,v*1.5),x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t;if(w==='grenade'||w==='bomb')y-=Math.sin(t*Math.PI)*28*zoom;if(w==='machine'){for(var k=0;k<3;k++){var z=Math.max(0,t-k*.13);ctx.beginPath();ctx.moveTo(a.x+(b.x-a.x)*z,a.y+(b.y-a.y)*z);ctx.lineTo(a.x+(b.x-a.x)*Math.max(0,z-.08),a.y+(b.y-a.y)*Math.max(0,z-.08));ctx.stroke();}}else{if(w==='missile'){ctx.globalAlpha=.4;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(x,y);ctx.stroke();ctx.globalAlpha=1;}disk(x,y,(w==='plasma'?5:3)*zoom,f.color);}if(t===1){ctx.globalAlpha=1-v;var radius=(w==='bomb'||w==='grenade'||w==='cannon'?18:7)*(v-.6)*3*zoom;ctx.beginPath();ctx.arc(b.x,b.y,Math.max(1,radius),0,Math.PI*2);ctx.stroke();}}ctx.restore();}

function open(html){modal.innerHTML='<div class="sheet">'+html+'</div>';modal.style.display='flex';windowNav243();}function close(){modal.style.display='none';drawNeeded=true;}function act(code){return code;}function cardSprite(i){if(i===19||i===20)return '<img class="icon" style="object-fit:contain;background:none" src="assets/'+(i===19?'attack-helicopter-221.webp':'heavy-bomber-221.webp')+'" alt="">';if(i>=23)return '<img class="icon" style="object-fit:contain;background:none" src="assets/'+['crystalplant','crystalstore','goldstore','powerstore','garrison','missileturret','cannonturret','shield'][i-23]+'.webp" alt="">';if(i>=16)return'<span class="icon extra" style="background-position:'+((i-16)%3*50)+'% '+(Math.floor((i-16)/3)*50)+'%"></span>';return'<span class="icon" style="background-position:'+(i%4*100/3)+'% '+(Math.floor(i/4)*100/3)+'%"></span>';}
function hud(){var d=E.d;$('gold').textContent=Math.floor(d.gold)+' / '+E.resourceCapacity();$('energy').textContent=Math.floor(d.power)+' / '+E.resourceCapacity('power');$('gems').textContent=d.gems.toLocaleString();$('army').textContent=E.housing()+'/'+E.capacity();$('mode').textContent=screen==='home'?tr('ฐาน NOVA • Lv.')+E.hq():screen==='defense'?tr('ป้องกันฐาน • ระลอก ')+E.defense.wave:(E.raid.player?tr('ทดสอบบุก • ')+E.raid.name:tr('บุกฐานต่างดาว • ด่าน ')+E.raid.stage);$('homebar').style.display=screen==='home'?'flex':'none';$('raidbar').style.display=screen!=='home'?'block':'none';$('raidhint').textContent=screen==='defense'?tr('ป้อมป้องกันฐานอัตโนมัติ'):tr('เลือกทหาร → แตะขอบสีฟ้า');if(screen==='defense'){$('clock').textContent=duration(E.defense.time);setHTML219($('deploy'),'');$('instruction').textContent=tr('ป้อมโจมตีอัตโนมัติ • รักษาศูนย์บัญชาการให้รอด');}else if(screen==='raid'){var r=E.raid;$('clock').textContent=Math.ceil(r.time)+tr(' วินาที');if(r.liveMode!=='preview'&&r.liveMode!=='defender'&&!(liveRoom&&liveRoom.withdrawn))setHTML219($('deploy'),U.map(function(u,i){return'<button class="troop '+(i===deployKind?'active':'')+'" onclick="Game.unit('+i+')">'+cardSprite(u.sprite)+'<b>'+(r.army||d.army)[i]+'</b><small>'+u.name+'</small></button>';}).join(''));$('instruction').textContent=r.phase==='scout'?tr('แตะขอบสีฟ้าเพื่อปล่อยทหาร เริ่มรบเมื่อปล่อยตัวแรก'):tr('ทหารหาเป้าหมายอัตโนมัติ • ปล่อยกำลังเสริมที่ขอบสีฟ้า');}else{$('instruction').textContent=placing?tr('แตะช่องสีเขียวเพื่อวาง ')+B[placing].name:moving?tr('ลากอาคาร • ✓ วาง / ✕ ยกเลิก'):mt251('แตะอาคารเพื่อจัดการ • ลากพื้นที่เพื่อเลื่อน','Tap a building to manage • Drag to pan');}var b=E.d.buildings.find(function(b){return b.id===selected;});$('selection').style.display=screen==='home'&&b&&!placing&&!moving?'block':'none';if(b){var c=E.upgradeCost(b);$('selection').innerHTML='<div class="selection-heading">'+(b.type==='wall'?'<span style="font-size:24px">▰</span>':cardSprite(B[b.type].sprite))+'<b>'+B[b.type].name+' <small>Lv.'+b.lv+'</small></b></div><div><button onclick="Game.upgrade()" '+(b.until||b.lv>=MAX_BUILDING_LEVEL?'disabled':'')+'>'+(b.until?(b.constructing?tr('กำลังสร้าง '):tr('อัปเกรด '))+duration((b.until-E.now())/1000):b.lv>=MAX_BUILDING_LEVEL?tr('ระดับสูงสุด'):tr('อัปเกรด')+' ('+(false?resourceIcon238('crystals')+' '+(200*b.lv*b.lv):resourceIcon238('gold')+' '+c.gold+' / '+resourceIcon238('power')+' '+c.power+(c.crystals?' / '+resourceIcon238('crystals')+' '+c.crystals:''))+')')+'</button>'+(b.until?tr('<button class="gem" onclick="Game.speedConfirm()">💎 เร่ง ')+E.speedCost(b.id)+'</button>':'')+'</div>'+(b.type==='tech'?tr('<small>ปลดล็อกหน่วยใหม่ทุกระดับ 1–5</small>'):b.type==='storage'?tr('<small>เพิ่มความจุทองและพลังงานอย่างละ ')+20000*b.lv+'</small>':'');$('selection').innerHTML+=defenseInfo223(b);if(b.type==='mercenary')$('selection').innerHTML+=tr('<button class="wide" onclick="Game.mercenaries()">ทหารรับจ้างต่างดาว</button>');if(b.type==='garrison')$('selection').innerHTML+=tr('<button class="wide" onclick="Game.garrison()">จัดกองกำลังป้องกัน ')+spaces(E.d.garrison)+' / '+E.garrisonCapacity()+'</button>';if(b.type==='wall')$('selection').innerHTML+=tr('<button class="wide" onclick="Game.wallMenu()">อัปเกรดชิ้น / แถว / แนวที่เชื่อมกัน</button>');}drawNeeded=true;}
