function updateTraining(){if(!$('trainSummary')||modal.style.display==='none')return;$('trainSummary').textContent=tr('พื้นที่ ')+E.housing()+'/'+E.capacity()+tr(' • พลังงาน ')+Math.floor(E.d.power);U.forEach(function(u,i){var jobs=E.d.queue.filter(function(q){return q.kind===i;}),lock=E.unitLock(i),reason=lock||(E.housing()+u.space>E.capacity()?tr('พื้นที่ไม่พอ'):E.d.power<u.cost?tr('พลังงานไม่พอ'):E.d.crystals<(u.crystals||0)?tr('ผลึกไม่พอ'):tr('พร้อมผลิต'));$('trainButton'+i).disabled=!!lock||E.housing()+u.space>E.capacity()||E.d.power<u.cost||E.d.crystals<(u.crystals||0);$('trainClock'+i).hidden=!jobs.length;$('trainStatus'+i).textContent=jobs.length?tr('กำลังผลิต ')+jobs.length+tr(' • ตัวถัดไป ')+duration((Math.min.apply(null,jobs.map(function(q){return q.until;}))-E.now())/1000):reason;});$('queue').textContent=queueText();}

