root.novaRewardEarned=function(id){if(E.reward(id)){toast(tr('ได้รับ 5 เพชรแล้ว'));hud();treasury();}if(!E.saveFailed&&root.NovaAds&&root.NovaAds.acknowledgeReward)root.NovaAds.acknowledgeReward(id);};
root.novaRewardStatus=function(status){var messages={ready:tr('โฆษณาพร้อมแล้ว กดดูโฆษณาอีกครั้งเพื่อรับรางวัล'),unconfigured:tr('โฆษณารางวัลยังไม่เปิดให้บริการ'),disabled:tr('เปิดโฆษณาในเมนูความเป็นส่วนตัวก่อน'),loading:tr('กำลังโหลดโฆษณา ลองอีกครั้งสักครู่'),unavailable:tr('ไม่มีโฆษณาพร้อมในขณะนี้'),cooldown:tr('รอ 2 นาทีก่อนรับโฆษณาครั้งต่อไป'),limit:tr('รับรางวัลโฆษณาครบวันนี้แล้ว'),closed:tr('ปิดโฆษณาแล้ว')};toast(messages[status]||tr('โปรดลองอีกครั้ง'));};
root.Game={treasury:treasury,speedConfirm:speedConfirm,speed:function(id,price){toast(E.speed(id,price)||tr('ก่อสร้างเสร็จแล้ว'));close();hud();},tradeConfirm:function(kind){open(tr('<h2>แลกทรัพยากร</h2><p>ใช้ 10 เพชร แลก 5,000 ')+(kind==='gold'?tr('ทอง'):tr('พลังงาน'))+'</p><button class="wide green" onclick="Game.trade(\''+kind+tr('\')">ยืนยันแลก</button><button class="wide" onclick="Game.treasury()">กลับ</button>'));},trade:function(kind){toast(E.exchange(kind)||tr('แลกทรัพยากรแล้ว'));hud();treasury();},checkin:function(){var n=E.claim();toast(n?tr('รับ ')+n+tr(' เพชรแล้ว'):tr('รับรางวัลวันนี้แล้ว'));hud();treasury();},rewardAd:function(){if(root.NovaAds&&root.NovaAds.reward)root.NovaAds.reward();else root.novaRewardStatus('unconfigured');},home:home,close:close,build:buildMenu,training:trainMenu,missions:missions,place:function(k){placing=k;moving=null;selected=null;close();hud();},train:function(i){var msg=E.train(i);if(msg)toast(msg);updateTraining();hud();},collect:function(){var v=E.collect();toast(tr('เก็บ ')+v.gold+tr(' ทอง / ')+v.power+tr(' พลังงาน'));hud();},upgrade:function(){var wall=E.d.buildings.find(function(b){return b.id===selected&&b.type==='wall';});if(wall){Game.wallConfirm('one');return;}var msg=E.upgrade(selected);toast(msg||tr('เริ่มอัปเกรดแล้ว'));hud();},scout:function(n){if(!E.d.army.some(function(n){return n>0;})&&!(E.d.mercenaries&&E.d.mercenaries.attack)){toast(tr('ฝึกทหารก่อนออกบุก'));return;}if(!E.scout(n))return;screen='raid';paused=false;selected=null;placing=null;moving=null;panX=panY=0;zoom=1;close();hud();},unit:function(i){deployKind=i;hud();},pause:pause,resume:function(){paused=false;close();last=performance.now();},retreat:function(){E.finish();paused=false;result();},zoom:function(v){zoom=Math.max(.35,Math.min(1.5,zoom+v));drawNeeded=true;},cancel:function(){placing=null;moving=null;selected=null;hud();},help:function(){open(tr('<h2>ผู้บัญชาการ ยินดีต้อนรับ!</h2><p>1. เหมืองและเครื่องสกัดส่งผลผลิตเข้าคลังอัตโนมัติจนเต็ม<br>2. สร้างฐาน อัปเกรดศูนย์บัญชาการเพื่อปลดล็อกโรงงาน<br>3. ฝึกกองทัพ แล้วออกบุกฐานต่างดาว<br>4. เลือกชนิดทหาร แล้วแตะขอบสีฟ้าเพื่อปล่อยกำลัง</p><p>ฐานหลักเล่นออฟไลน์ได้ • เปิดสงครามออนไลน์ผ่านเมนูภารกิจเพื่อบุกผู้เล่นที่เข้าร่วม<br>ทหารที่ส่งออกรบจะถูกใช้ไป ฝึกทดแทนได้</p><button class="wide green" onclick="Game.close()">เริ่มบัญชาการ</button><button class="wide" onclick="Game.privacy()">ความเป็นส่วนตัว / โฆษณา</button>'));},privacy:function(){open(tr('<h2>ความเป็นส่วนตัว</h2><p>Nova Striker • Cockro Network<br>เล่นออฟไลน์ได้โดยไม่สมัคร ข้อมูลฐานอยู่ในอุปกรณ์ การลบข้อมูลแอปทำให้เซฟในเครื่องหาย<br>เมื่อล็อกอินด้วย Google จะสำรองเซฟไป Supabase ได้ตามที่คุณเลือก<br>เมื่อเข้าร่วมสงครามออนไลน์ จะเก็บผังฐาน ระดับ และรายงานการรบ ผู้เล่นอื่นเห็นรหัสผู้บัญชาการและแนวป้องกัน<br>ถอนฐานและลบข้อมูลสงครามได้จากเมนูออนไลน์ ส่วนเซฟคลาวด์ลบได้จากเมนูบัญชี</p><p>Google Ads อาจใช้ IP รหัสโฆษณา และข้อมูลการใช้งานตามความยินยอมของคุณ</p><button class="wide" onclick="if(window.NovaAds)NovaAds.settings()">ตั้งค่าโฆษณา</button><p><a href="https://nova-striker-privacy.fit-rain-4305.chatgpt.site">นโยบายฉบับเต็ม</a><br>sunan.tongsan@gmail.com</p><button class="wide" onclick="Game.close()">กลับ</button>'));}};
var audio=null,soundOn=localStorage.getItem('novaSound')!=='off';
function sound(freq,length){if(!soundOn||!audio||audio.state!=='running')return;try{var o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+length);}catch(e){}}
document.addEventListener('pointerdown',function(){if(!soundOn)return;try{if(!audio){var A=root.AudioContext||root.webkitAudioContext;if(A)audio=new A();}if(audio&&audio.state==='suspended')audio.resume();}catch(e){}},{passive:true});
Game.resources=function(){E.sync();open(tr('<h2>คลังทรัพยากร</h2><p>ทอง ')+Math.floor(E.d.gold)+' / '+E.resourceCapacity('gold')+tr('<br>พลังงาน ')+Math.floor(E.d.power)+' / '+E.resourceCapacity('power')+tr('</p><p>ผลผลิตเข้าคลังอัตโนมัติ แม้ปิดเกม จนคลังเต็ม<br>อัปเกรดฐานหลักหรือคลังเสบียงเพื่อเพิ่มความจุ<br>ยอดเก่าเกินความจุจะยังอยู่ แต่ผลผลิตหยุดจนมีพื้นที่</p><p>ทอง ')+(E.d.buildings.filter(function(b){return b.type==='mine'&&active(b);}).reduce(function(n,b){return n+36*b.lv;},0))+tr(' / นาที<br>พลังงาน ')+(E.d.buildings.filter(function(b){return b.type==='reactor'&&active(b);}).reduce(function(n,b){return n+36*b.lv;},0))+tr(' / นาที</p><button class="wide" onclick="Game.close()">กลับ</button>'));hud();};
Game.wallMenu=function(){open(tr('<h2>จัดการแนวกำแพง</h2><p>เชื่อมอัตโนมัติเมื่อวางติดช่องแนวเดียวกัน • ไม่เชื่อมแนวทแยง<br>เลือกกลุ่มแล้วตรวจราคาก่อนยืนยัน</p>')+[['one',tr('ชิ้นนี้')],['x',tr('แถวแนว ↘')],['y',tr('แถวแนว ↙')],['all',mt251('กำแพงทั้งหมดในฐาน','All walls in base')]].map(function(a){var q=E.wallQuote(selected,a[0]);return'<button class="wide" '+(!q.ids.length?'disabled ':'')+'onclick="Game.wallConfirm(\''+a[0]+'\')">'+a[1]+' • '+q.ids.length+tr(' ชิ้น • ')+q.gold+tr(' ทอง / ')+q.power+tr(' พลังงาน</button>');}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.wallConfirm=function(mode){var q=E.wallQuote(selected,mode);wallPending={id:selected,mode:mode,quote:JSON.stringify(q)};open(tr('<h2>ยืนยันอัปเกรดกำแพง</h2><p>')+q.ids.length+tr(' ชิ้น • ')+q.gold+tr(' ทอง / ')+q.power+tr(' พลังงาน<br>')+mt251('อัปเกรดทันที เพิ่มชิ้นละ 1 ระดับ','Instant upgrade: +1 level per wall')+tr('</p><button class="wide green" onclick="Game.wallApply()">ยืนยันอัปเกรด</button><button class="wide" onclick="Game.wallMenu()">กลับ</button>'));};
Game.wallApply=function(){if(!wallPending)return;toast(E.upgradeWalls(wallPending.id,wallPending.mode,wallPending.quote)||tr('อัปเกรดแนวกำแพงแล้ว'));wallPending=null;close();hud();};
Game.speedQueue=function(){E.sync();if(!E.d.queue.length){toast(tr('คิวฝึกว่าง'));return;}var cost=Math.ceil((Math.max.apply(null,E.d.queue.map(function(q){return q.until;}))-E.now())/10000);open(tr('<h2>เร่งฝึกทั้งหมด</h2><p>')+E.d.queue.length+tr(' หน่วย • ใช้ ')+cost+tr(' เพชร</p><button class="wide green" onclick="Game.finishQueue(')+cost+tr(')">ยืนยัน</button><button class="wide" onclick="Game.training()">กลับ</button>'));};
Game.finishQueue=function(cost){toast(E.speedTraining(cost)||tr('กองทัพพร้อมแล้ว'));trainMenu();hud();};
Game.activities=function(){open(tr('<h2>ศูนย์ภารกิจ</h2><button class="wide green" onclick="Game.findWar()">🌐 ทำสงคราม</button><button class="wide green" onclick="Game.defenseInfo()">👾 ป้องกันฐาน • ระลอก ')+E.d.defenseLevel+tr('</button><button class="wide" onclick="Game.garrison()">กองกำลังป้องกันฐาน</button><button class="wide" onclick="Game.tasks()">🎯 ภารกิจรายวัน</button><button class="wide" onclick="Game.missions()">⚔ แผนที่ต่างดาว • บอสทุก 5 ด่าน</button><button class="wide" onclick="Game.cloud()">☁ บัญชีและเซฟออนไลน์</button><button class="wide" onclick="Game.toggleSound()">เสียง: ')+(soundOn?tr('เปิด'):tr('ปิด'))+tr('</button><button class="wide" onclick="Game.close()">กลับฐาน</button>'));};
Game.toggleSound=function(){soundOn=!soundOn;try{localStorage.setItem('novaSound',soundOn?'on':'off');}catch(e){}Game.activities();};
Game.tasks=function(){var t=E.d.tasks,today=t.day===E.day();open(tr('<h2>ภารกิจประจำวัน</h2><p>แต่ละภารกิจให้ 5 เพชร • รีเซ็ตเที่ยงคืนไทย</p>')+[['build',2,tr('สร้างหรืออัปเกรด')],['train',5,tr('ฝึกทหารสำเร็จ')],['win',2,tr('ชนะด่านบุก')],['defend',1,tr('ป้องกันฐานสำเร็จ')]].map(function(a){var count=today?t[a[0]]||0:0,claimed=today&&t.claimed.indexOf(a[0])>=0;return'<button class="wide" '+(claimed||count<a[1]?'disabled':'')+' onclick="Game.claimTask(\''+a[0]+'\')">'+a[2]+' '+Math.min(count,a[1])+'/'+a[1]+' • '+(claimed?tr('รับแล้ว'):tr('รับ 5 💎'))+'</button>';}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.claimTask=function(k){toast(E.claimTask(k)?tr('รับ 5 เพชรแล้ว'):tr('ยังรับไม่ได้'));Game.tasks();hud();};
Game.defenseInfo=function(){open(tr('<h2>ต่างดาวบุกฐาน</h2><p>ระลอก ')+E.d.defenseLevel+tr(' • เตรียมป้อมและกำแพงก่อนเริ่ม<br>กำจัดศัตรูทั้งหมดใน 2 นาทีและรักษาฐานหลัก<br>ชนะรับทรัพยากรและ 3 เพชร ปลดล็อกระลอกถัดไป<br>เป็นโหมดฝึกป้องกัน ความเสียหายจะซ่อมคืนฟรีเมื่อจบ ไม่เสียอาคารถาวร</p><button class="wide green" onclick="Game.startDefense()">เริ่มป้องกันฐาน</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.startDefense=function(){var msg=E.startDefense();if(msg){toast(msg);return;}screen='defense';selected=null;placing=moving=null;paused=false;zoom=.85;panX=0;panY=-110;close();hud();};
function defenseResult(){var r=E.defense.result;open('<h2>'+(r.win?tr('ป้องกันฐานสำเร็จ!'):tr('ฐานถูกยึด'))+tr('</h2><p>ได้ ')+r.gold+tr(' ทอง / ')+r.power+tr(' พลังงาน / ')+r.gems+tr(' เพชร<br>อาคารทุกหลังจะซ่อมคืนให้พร้อมลองใหม่</p><button class="wide green" onclick="Game.home()">กลับฐาน</button>'));hud();}
Game.endDefense=function(){E.finishDefense(false);paused=false;defenseResult();};
var cloudRevision=0,cloudLoaded=false,cloudCandidate=null,loginDestination="cloud";
function safeCampaign(d){return d&&d.version===1&&Number.isFinite(d.gold)&&d.gold>=0&&Number.isFinite(d.power)&&d.power>=0&&Number.isFinite(d.gems)&&d.gems>=0&&Number.isInteger(d.next)&&Array.isArray(d.buildings)&&d.buildings.length>0&&d.buildings.length<=200&&d.buildings.filter(function(b){return b.type==='hq';}).length===1&&d.buildings.every(function(b){return B[b.type]&&Number.isInteger(b.id)&&Number.isInteger(b.x)&&b.x>=1&&b.x<=20&&Number.isInteger(b.y)&&b.y>=1&&b.y<=20&&Number.isInteger(b.lv)&&b.lv>=1&&b.lv<=MAX_BUILDING_LEVEL&&(!b.until||Number.isFinite(b.until));})&&new Set(d.buildings.map(function(b){return b.id;})).size===d.buildings.length&&new Set(d.buildings.map(function(b){return b.x+','+b.y;})).size===d.buildings.length&&d.next>Math.max.apply(null,d.buildings.map(function(b){return b.id;}))&&Array.isArray(d.army)&&d.army.length>=9&&d.army.length<=U.length&&d.army.every(function(n){return Number.isInteger(n)&&n>=0&&n<=10000;})&&Array.isArray(d.queue)&&d.queue.length<=300&&d.queue.every(function(q){return Number.isInteger(q.kind)&&U[q.kind]&&Number.isFinite(q.until);})&&Number.isFinite(d.last)&&Number.isInteger(d.stage)&&d.stage>=1&&d.stage<=20&&d.stars&&typeof d.stars==='object'&&(!d.tasks||Number.isInteger(d.tasks.day)&&Array.isArray(d.tasks.claimed))&&(!d.checkin||Number.isInteger(d.checkin.day)&&Number.isInteger(d.checkin.streak))&&(!d.rewardIds||Array.isArray(d.rewardIds));}
Game.cloud=function(){loginDestination="cloud";if(root.NovaCloud&&root.NovaCloud.provider==='telegram'){open('<h2>'+tr('บัญชีและเซฟออนไลน์')+'</h2><p>Telegram • '+tr('โหลดรายการเซฟก่อนเลือกว่าจะสำรองหรือกู้คืน')+'</p><button class="wide" onclick="Game.cloudLogin()">'+mt251('เข้าสู่ระบบด้วย Telegram','Sign in with Telegram')+'</button><button class="wide" onclick="Game.cloudLoad()">'+tr('ตรวจเซฟออนไลน์')+'</button><button class="wide" onclick="Game.close()">'+tr('กลับ')+'</button>');return;}var ready=root.NovaCloud&&root.NovaCloud.available();open(tr('<h2>บัญชีและเซฟออนไลน์</h2><p>')+(ready?tr('อีเมล หรือบัญชี Google • เก็บเซฟข้ามเครื่อง<br>โหลดรายการเซฟก่อนเลือกว่าจะสำรองหรือกู้คืน'):tr('กำลังเตรียมเปิด Google Login และเซฟออนไลน์<br>รุ่นนี้ยังบันทึกฐานในเครื่องตามเดิม'))+'</p><button class="wide" '+(!ready?'disabled':'')+tr(' onclick="Game.cloudLogin()">เข้าสู่ระบบด้วย Google</button><button class="wide" ')+(!ready?'disabled':'')+tr(' onclick="Game.cloudLoad()">ตรวจเซฟออนไลน์</button><button class="wide" onclick="Game.emailForm()">อีเมล / รหัสผ่าน</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.emailForm=function(mode){mode=mode||'login';var signup=mode==='signup',reset=mode==='recover',update=mode==='update';open('<h2>'+(signup?tr('สมัครด้วยอีเมล'):reset?tr('ลืมรหัสผ่าน'):update?tr('ตั้งรหัสผ่านใหม่'):tr('เข้าสู่ระบบด้วยอีเมล'))+'</h2><form onsubmit="Game.emailSubmit(event,\''+mode+'\')">'+(!update?tr('<label>อีเมล<input id="authEmail" type="email" autocomplete="email" maxlength="254" required style="display:block;width:100%;box-sizing:border-box;padding:12px;font-size:16px"></label>'):'')+(!reset?tr('<label>รหัสผ่าน<input id="authPassword" type="password" autocomplete="')+(signup||update?'new-password':'current-password')+'" minlength="'+(signup||update?8:1)+'" maxlength="128" required style="display:block;width:100%;box-sizing:border-box;padding:12px;font-size:16px"></label>':'')+(signup?tr('<p>รหัสผ่านอย่างน้อย 8 ตัวอักษร ต้องยืนยันอีเมลก่อนเข้าเล่น</p>'):'')+'<button class="wide green" type="submit">'+(signup?tr('สมัครสมาชิก'):reset?tr('ส่งลิงก์ตั้งรหัสผ่าน'):update?tr('บันทึกรหัสผ่าน'):tr('เข้าสู่ระบบ'))+'</button></form>'+(!update?'<button class="wide" onclick="Game.emailForm(\''+(signup?'login':'signup')+'\')">'+(signup?tr('มีบัญชีแล้ว'):tr('สมัครสมาชิกใหม่'))+tr('</button><button class="wide" onclick="Game.emailForm(\'recover\')">ลืมรหัสผ่าน</button>'):'')+tr('<button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.emailSubmit=function(event,mode){event.preventDefault();var email=$('authEmail')?$('authEmail').value.trim():'',password=$('authPassword')?$('authPassword').value:'';if(!root.NovaCloud||!root.NovaCloud.emailAuth){toast(tr('ใช้งานผ่านแอป Android รุ่นล่าสุด'));return;}if($('authPassword'))$('authPassword').value='';root.NovaCloud.emailAuth(mode,email,password);toast(tr('กำลังดำเนินการ'));};
Game.cloudLogin=function(){if(root.NovaCloud){cloudLoaded=false;root.NovaCloud.login();}};
Game.cloudLoad=function(){if(root.NovaCloud){cloudLoaded=false;toast(tr('กำลังตรวจเซฟออนไลน์'));root.NovaCloud.load();}};
Game.cloudUpload=function(){if(!cloudLoaded)return;open(tr('<h2>สำรองฐานเครื่องนี้?</h2><p>บันทึกฐานปัจจุบันแทนเซฟออนไลน์ของบัญชีที่ล็อกอิน<br>ยอดเพชรนี้เป็นของโหมดออฟไลน์ ไม่ใช่ยอดซื้อเงินจริง</p><button class="wide green" onclick="Game.cloudUploadNow()">ยืนยันสำรอง</button><button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.cloudUploadNow=function(){if(!cloudLoaded)return;E.sync();cloudLoaded=false;root.NovaCloud.save(JSON.stringify(E.d),cloudRevision);toast(tr('กำลังสำรองฐาน'));};
Game.cloudRestore=function(){if(!cloudCandidate||!safeCampaign(cloudCandidate))return;open(tr('<h2>กู้คืนฐานจากคลาวด์?</h2><p>ฐานในเครื่องจะเปลี่ยนเป็นเซฟที่เลือก<br>จะเก็บสำเนาฐานเดิมไว้ในเครื่องก่อนแทนที่</p><button class="wide green" onclick="Game.cloudRestoreNow()">ยืนยันกู้คืน</button><button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.cloudRestoreNow=function(){if(!cloudCandidate||!safeCampaign(cloudCandidate))return;try{localStorage.setItem('novaRTSBeforeRestore',JSON.stringify(E.d));localStorage.setItem('novaRTS1',JSON.stringify(cloudCandidate));E=new Engine(localStorage);cloudCandidate=null;home();toast(tr('กู้คืนฐานแล้ว'));}catch(e){toast(tr('บันทึกในเครื่องไม่สำเร็จ ยังไม่เปลี่ยนฐาน'));}};
Game.cloudDelete=function(){open(tr('<h2>ลบเซฟ Nova ออนไลน์?</h2><p>ลบเฉพาะข้อมูล Nova ในบัญชีนี้ถาวร เซฟในเครื่องและข้อมูลเกมอื่นไม่ถูกลบ</p><button class="wide" onclick="Game.cloudDeleteNow()">ยืนยันลบเซฟออนไลน์</button><button class="wide" onclick="Game.cloud()">ยกเลิก</button>'));};
Game.cloudDeleteNow=function(){root.NovaCloud.deleteSave();};
root.novaCloudEvent=function(event,data){if(event==='signed_in'||event==='signed_out'){testWallet=null;testTarget=null;clearTimeout(warTimer);warBusy=false;warActive=null;}if(event.indexOf('war')===0){warEvent(event,data);return;}if(event==='password_recovery'){Game.emailForm('update');return;}if(event==='status'){toast(data.message);return;}if(event==='signed_in'){warPending=null;warState=null;cloudLoaded=false;cloudCandidate=null;cloudRevision=0;if(loginDestination==='test'){loginDestination='cloud';Game.testShop();}else if(loginDestination==='war'){loginDestination='cloud';Game.war();}else Game.cloudLoad();return;}if(event==='loaded'){cloudRevision=data.save?data.save.revision:0;cloudLoaded=true;cloudCandidate=data.save?data.save.payload:null;var valid=cloudCandidate&&safeCampaign(cloudCandidate);open(tr('<h2>เซฟบัญชีของคุณ</h2><p>')+(data.save?tr('พบเซฟออนไลน์รุ่นที่ ')+cloudRevision:tr('ยังไม่มีเซฟออนไลน์'))+tr('</p><button class="wide green" onclick="Game.cloudUpload()">สำรองฐานเครื่องนี้</button>')+(valid?tr('<button class="wide" onclick="Game.cloudRestore()">กู้คืนฐานจากออนไลน์</button>'):'')+tr('<button class="wide" onclick="Game.cloudDelete()">ลบเซฟ Nova ออนไลน์</button><button class="wide" onclick="NovaCloud.logout()">ออกจากระบบ</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(event==='saved'){cloudRevision=data.revision;cloudLoaded=true;toast(tr('สำรองฐานออนไลน์แล้ว'));close();}if(event==='deleted'||event==='signed_out'){warPending=null;warState=null;cloudLoaded=false;cloudCandidate=null;cloudRevision=0;toast(event==='deleted'?tr('ลบเซฟออนไลน์แล้ว'):tr('ออกจากระบบแล้ว'));Game.cloud();}};

var warState=null,warBusy=false,warPending=null,warTimer=null,warSerial=0,warActive=null,lastWarRequest=null;
function escapeHTML(v){return String(v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function warRequest(action,payload){
 if(warBusy){toast(tr('กำลังรอผลรายการเดิม กรุณารอสักครู่'));return;}
 if(!root.NovaCloud||!root.NovaCloud.warAvailable()){Game.war();return;}
 var id=String(++warSerial);warActive=id;warBusy=true;lastWarRequest={action:action,payload:payload||{}};
 var label=action==='test_claim'?tr('กำลังรับเพชรประจำวัน'):action.indexOf('test_')===0?tr('กำลังเชื่อมต่อศูนย์เพชร'):tr('กำลังติดต่อกองบัญชาการออนไลน์');
 if(resourcePolling||payload&&(payload.live||payload.enhance)){}else if(E.d.pendingCrystal||E.d.pendingWar||infrastructureAfterPublish){toast(tr('กำลังดำเนินการ…'));}else open('<h2>'+label+tr('</h2><p>กำลังโหลด…</p><button class="wide" onclick="Game.close()">กลับ</button>'));
 warTimer=setTimeout(function(){if(warActive!==id)return;warEvent('war_error',{request_id:id,message:tr('การเชื่อมต่อใช้เวลานาน กรุณาตรวจอินเทอร์เน็ตแล้วลองอีกครั้ง หากรับรางวัลสำเร็จแล้ว ระบบจะคืนยอดเดิม ไม่รับซ้ำ')});},45000);
 try{if(root.NovaCloud.warRequest)root.NovaCloud.warRequest(action,JSON.stringify(payload||{}),id);else root.NovaCloud.war(action,JSON.stringify(payload||{}));}catch(e){warEvent('war_error',{request_id:id,message:tr('เชื่อมต่อระบบออนไลน์ไม่ได้ กรุณาปิดแล้วเปิดเกมใหม่')});}
}
Game.retryWarRequest=function(){if(!lastWarRequest)return;var a=lastWarRequest.action,p=lastWarRequest.payload;if(a.indexOf('test_')===0||['status','history','targets'].includes(a)||p.request_id)warRequest(a,p);else warRequest('status');};
Game.war=function(){if(!root.NovaCloud||!root.NovaCloud.warAvailable()){open(tr('<h2>ทำสงคราม</h2><p>กำลังเตรียมเปิดให้บริการออนไลน์</p><p>บุกฐานผู้เล่นจริงแม้เจ้าของออฟไลน์ เลือกแผนแล้วรับรายงานการรบอัตโนมัติ<br>โล่หลังถูกบุก 30 นาที • พักจู่โจม 3 นาที<br>รุ่นนี้ยังเล่นด่านต่างดาวและป้องกันฐานออฟไลน์ได้ตามปกติ</p><button class="wide" onclick="Game.activities()">กลับ</button>'));return;}warRequest('status');};
function warMenu(){var d=warState;if(!d||!d.enrolled){open(tr('<h2>เข้าร่วมสงครามออนไลน์</h2><p>ส่งผังฐานปัจจุบันเข้าสนามรบ ผู้เล่นอื่นจะเห็นรหัสผู้บัญชาการและฐานของคุณ<br>สร้างโรงสังเคราะห์และคลังผลึกในฐานก่อน ส่งผังเพื่อเริ่มผลิตบนเซิร์ฟเวอร์<br>เมื่อเข้าร่วม ยอดผลึกในเครื่องจะเปลี่ยนเป็นยอดออนไลน์เดิม (บัญชีใหม่เริ่ม 0) ไม่บวกสองยอดรวมกัน<br>ใช้หน่วยจู่โจมออนไลน์ประจำการ เลือกแผนรบเพื่อส่งกำลัง</p><button class="wide green" onclick="Game.warPublish(true)">เข้าร่วมและส่งผังฐาน</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}var now=Date.parse(d.server_time),shield=Math.max(0,(Date.parse(d.shield_until)-now)/1000),cool=Math.max(0,(Date.parse(d.raid_after)-now)/1000);open(tr('<h2>ทำสงคราม</h2><p>')+escapeHTML(d.callsign)+tr(' • ระดับ ')+d.tier+'<br>🔮 '+d.crystals+' / '+d.capacity+tr(' • ผลิต ')+(d.rate||0)+tr(' / ชั่วโมง<br>ปล้นได้สูงสุด 60% • โล่ ')+duration(shield)+tr(' • หน่วยจู่โจมพัก ')+duration(cool)+tr('</p><button class="wide green" onclick="Game.warTargets()">ค้นหาคู่ต่อสู้</button><button class="wide" onclick="Game.warUpgrade()" ')+(d.tier>=15?'disabled':'')+tr('>ยกระดับกองกำลังและเกราะ • ')+(d.tier>=15?tr('สูงสุด'):d.tier*150+tr(' ผลึก'))+tr('</button><button class="wide" onclick="Game.onlineArsenal()">คลังแสง / กองกำลังป้องกันออนไลน์</button><button class="wide" onclick="Game.warPublish(false)">ส่งผังฐานปัจจุบันเพื่อเริ่มโรงผลิตผลึก</button><button class="wide" onclick="Game.retryOnline()">ตรวจรายการออนไลน์ค้าง</button><button class="wide" onclick="Game.warHistory()">รายงานบุก / ป้องกัน</button><button class="wide" onclick="Game.war()">รีเฟรชผลึกและเวลา</button><button class="wide" onclick="Game.warLeave()">ถอนฐานและลบข้อมูลสงคราม</button><button class="wide" onclick="Game.close()">กลับฐาน</button>'));}
Game.warPublish=function(enroll){warRequest(enroll?'enroll':'publish',{layout:E.d.buildings.filter(active).map(function(b){return{type:b.type,x:b.x,y:b.y,lv:b.lv};})});};
var targetCursor=-1;Game.practiceTargets=function(){warRequest('test_targets',{previous:testTarget&&testTarget.id});};Game.warTargets=function(after){targetCursor=-1;warRequest('targets',after?{after:after}:{});};Game.nextTarget=function(){if(warState&&warState.targets&&targetCursor+1<warState.targets.length){Game.warScout(++targetCursor);}else Game.warTargets(warState&&warState.targets&&warState.targets.length?warState.targets[warState.targets.length-1].id:null);};Game.warHistory=function(){warRequest('history');};
Game.warUpgrade=function(){if(!warState)return;open(tr('<h2>อัปเกรดกองกำลังออนไลน์</h2><p>ใช้ ')+warState.tier*150+tr(' ผลึก เพิ่มพลังจู่โจมและเกราะป้องกัน 1 ระดับ</p><button class="wide green" onclick="Game.warUpgradeNow()">ยืนยัน</button><button class="wide" onclick="Game.war()">กลับ</button>'));};Game.warUpgradeNow=function(){warRequest('upgrade');};
Game.warLeave=function(){open(tr('<h2>ถอนฐานออนไลน์?</h2><p>ลบระดับและรายงานสงครามของคุณถาวร ฐานออฟไลน์ยังอยู่</p><button class="wide" onclick="Game.warLeaveNow()">ยืนยันถอนฐานและลบข้อมูล</button><button class="wide" onclick="Game.war()">ยกเลิก</button>'));};Game.warLeaveNow=function(){warRequest('leave');};
function basePreview(layout){return tr('<svg viewBox="0 0 220 220" style="width:100%;max-height:240px;background:#365b43;border-radius:12px" aria-label="ผังฐานคู่ต่อสู้">')+layout.map(function(b){var color=b.type==='hq'?'#ffd36a':b.type==='wall'?'#a4adb2':['gun','tesla','cannonturret','missileturret'].includes(b.type)?'#f87865':'#84d8df';return '<rect x="'+(b.x*10-5)+'" y="'+(b.y*10-5)+'" width="9" height="9" rx="2" fill="'+color+'"/>';}).join('')+'</svg>';}
Game.warScout=function(index){targetCursor=index;var t=warState.targets[index];if(!t)return;warState.target=t;open('<h2>'+escapeHTML(t.callsign)+'</h2>'+basePreview(t.layout)+tr('<p>ระดับ ')+t.tier+tr(' • ปล้นได้สูงสุด<br>')+(t.loot_gold||0)+tr(' ทอง / ')+(t.loot_power||0)+tr(' พลังงาน</p>')+(t.can_attack===false?tr('<p>ฐานนี้มีโล่หรืออยู่ในช่วงพักบุกซ้ำ</p>'):tr('<label>แผนโจมตี <select id="warTactic"><option value="siege">ยานเกราะปิดล้อม</option><option value="infantry">ทหารกระจายตัว</option><option value="air">โจมตีทางอากาศ</option></select></label>'))+'<button class="wide green" '+(t.can_attack===false?'disabled':'')+mt251(" onclick=\"Game.attackSelected()\">โจมตี</button><button class=\"wide\" onclick=\"Game.nextTarget()\">ค้นหาต่อ • 2 NOVA</button><button class=\"wide\" onclick=\"Game.close()\">กลับฐาน</button>"," onclick=\"Game.attackSelected()\">Attack</button><button class=\"wide\" onclick=\"Game.nextTarget()\">Next base • 2 NOVA</button><button class=\"wide\" onclick=\"Game.close()\">Home</button>"));};
Game.attackSelected=function(){Game.warAttack($('warTactic').value||'siege');};
Game.warAttack=function(tactic){if(warBusy||!warState.target)return;if(!warPending){var bytes=new Uint8Array(16);root.crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;var hex=Array.from(bytes).map(function(v){return('0'+v.toString(16)).slice(-2);}).join('');warPending={target:warState.target.id,tactic:tactic,request_id:hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20)};}warRequest('attack',warPending);};
function warEvent(event,message){if(message.request_id&&message.request_id!==warActive)return;clearTimeout(warTimer);warBusy=false;warActive=null;if(event==='war'&&message.action.indexOf('test_')===0){testEvent(message.action,message.data);return;}if(event==='war_login'){loginDestination=lastWarRequest&&lastWarRequest.action.indexOf('test_')===0?'test':'war';open(tr('<h2>เลือกวิธีเข้าเล่นออนไลน์</h2><p>เลือกสมัครด้วยอีเมล หรือเข้าสู่ระบบด้วย Google เพื่อเก็บความคืบหน้า</p><button class="wide green" onclick="Game.cloudLogin()">สมัคร / เข้าสู่ระบบ Google</button><button class="wide" onclick="Game.emailForm()">อีเมล / รหัสผ่าน</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(event==='war_error'){crystalPurchaseQuantity=0;open(tr('<h2>ยังไม่ได้รับผลจากเซิร์ฟเวอร์</h2><p>')+escapeHTML(message.message)+tr('</p><button class="wide green" onclick="Game.retryWarRequest()">ลองรายการเดิมอีกครั้ง</button><button class="wide" onclick="Game.testShop()">ตรวจยอดเพชรเดิม</button>')+(warPending?tr('<button class="wide green" onclick="Game.warRetry()">ตรวจรายการจู่โจมเดิมอีกครั้ง</button>'):'')+(E.d.pendingWar?tr('<button class="wide" onclick="Game.retryOnline()">ตรวจรายการออนไลน์เดิม</button><button class="wide" onclick="Game.cancelOnline()">ยกเลิกรายการที่ยังไม่สำเร็จ</button>'):'')+tr('<button class="wide" onclick="Game.war()">กลับกองบัญชาการ</button>'));return;}warState=message.data;var d=warState;if(message.action==='leave'){delete E.d.onlineCrystal;E.d.crystals=0;E.d.buildings.filter(function(b){return b.type==='crystalplant';}).forEach(function(b){b.collected=E.now();});E.save();}if(E.d.pendingWar&&message.action===E.d.pendingWar.action){delete E.d.pendingWar;E.save();}syncCrystal(d);if(message.action==='publish'&&infrastructureAfterPublish){var kind=infrastructureAfterPublish;infrastructureAfterPublish=null;warRequest('infrastructure',{kind:kind,economyVersion:2,request_id:nonce160()});return;}if(message.action==='infrastructure'){toast(d.receipt&&d.receipt.pending?tr('เริ่มอัปเกรดอาคารแล้ว'):tr('อัปเกรดอาคารสำเร็จ'));close();hud();return;}if(message.action==='cancel'){var receipt=d.receipt,p=E.d.pendingCrystal;if(receipt&&receipt.cancelled&&p&&receipt.id===p.request_id){E.d.gold+=p.gold||0;E.d.power+=p.power||0;delete E.d.pendingCrystal;}else if(p)finishCrystal(receipt);if(receipt&&E.d.pendingWar&&receipt.id===E.d.pendingWar.payload.request_id)delete E.d.pendingWar;E.save();Game.crystalCenter();return;}if(message.action==='fund'){finishCrystal(d.receipt);close();hud();return;}if(['forge','station'].includes(message.action)){onlineArsenal();return;}if(message.action==='research'){Game.crystalCenter();return;}if(message.action==='attack'&&d.report){warPending=null;open(tr('<h2>รายงานการจู่โจม</h2><p>ทำลาย ')+d.report.destruction+tr('%<br>ชิงทอง ')+(d.report.loot_gold||0)+tr('<br>ชิงพลังงาน ')+(d.report.loot_power||0)+tr('</p><button class="wide green" onclick="Game.war()">กลับกองบัญชาการ</button>'));return;}if(message.action==='targets'){if(d.targets.length){targetCursor=0;Game.warScout(0);return;}open('<h2>'+tr('ค้นหาผู้เล่น')+'</h2>'+(d.targets.length?d.targets.map(function(t,i){return'<button class="wide" onclick="Game.warScout('+i+')">'+escapeHTML(t.callsign)+' • Lv.'+t.tier+'</button>';}).join(''):tr('<p>ยังไม่พบฐานผู้เล่นอื่น • ฐานติดโล่ ')+(d.waiting_shield||0)+tr(' • รายการพักบุกซ้ำ ')+(d.waiting_rematch||0)+tr('<br>พักบุกคู่เดิม 30 นาที หรือเล่นด่านต่างดาวระหว่างรอ</p>'))+tr('<button class="wide" onclick="Game.war()">กลับ</button>'));return;}if(message.action==='history'){open(tr('<h2>รายงานสงคราม</h2>')+(d.history.length?d.history.map(function(r){return'<p>'+(r.attacking?tr('บุก'):tr('ถูกบุกโดย'))+' '+escapeHTML(r.opponent)+tr('<br>ทำลาย ')+r.destruction+'% • '+(r.attacking?'+':'−')+(r.loot_gold||0)+tr(' ทอง / ')+(r.loot_power||0)+tr(' พลังงาน<br>')+escapeHTML(new Date(r.created_at).toLocaleString('th-TH'))+'</p>';}).join(''):tr('<p>ยังไม่มีการรบ</p>'))+tr('<button class="wide" onclick="Game.war()">กลับ</button>'));return;}warMenu();}
Game.warRetry=function(){if(warPending)warRequest('attack',warPending);};

function nonce160(){var a=new Uint8Array(16);root.crypto.getRandomValues(a);a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;var s=Array.from(a,function(n){return('0'+n.toString(16)).slice(-2);}).join('');return s.slice(0,8)+'-'+s.slice(8,12)+'-'+s.slice(12,16)+'-'+s.slice(16,20)+'-'+s.slice(20);}
Game.garrison=function(){open(tr('<h2>กองกำลังป้องกันฐาน</h2><p>ประจำการ ')+spaces(E.d.garrison)+' / '+E.garrisonCapacity()+tr(' พื้นที่<br>ใช้ทหารที่ฝึกแล้ว • ถอนกลับได้ • หลังจบป้องกันกลับมาครบ<br>ชุดนี้ใช้ป้องกันต่างดาวในเครื่อง</p>')+U.map(function(u,i){return'<div class="def-row"><b>'+u.name+tr('</b><small>พื้นที่ ')+u.space+tr(' • พร้อม ')+E.d.army[i]+tr(' • ประจำการ ')+E.d.garrison[i]+'</small><button onclick="Game.station('+i+tr(',1)">+ ประจำการ</button><button onclick="Game.station(')+i+tr(',-1)">− ถอน</button></div>');}).join('')+tr('<button class="wide" onclick="Game.war()">กองกำลังออนไลน์บนเซิร์ฟเวอร์</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.station=function(i,d){toast(E.station(i,d)||tr('จัดกำลังแล้ว'));Game.garrison();hud();};
var crystalPurchaseQuantity=0;
Game.crystalExchange=function(){open(tr('<h2>แลกผลึก</h2><p>10 เพชร = 1,000 ผลึก</p>')+[1,10,100,1000].map(function(q){return '<button class="wide green" onclick="Game.buyCrystals('+q+')">'+(q*10).toLocaleString()+' 💎 → '+(q*1000).toLocaleString()+tr(' ผลึก</button>');}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.buyCrystals=function(q){if(!Number.isInteger(q)||q<1||q>1000)return;if(!E.d.onlineCrystal){toast(E.exchange('crystals',q)||tr('แลกผลึกแล้ว'));hud();Game.crystalExchange();return;}if(warBusy||E.d.pendingTest)return;if(E.d.gems<q*10){toast(tr('เพชรไม่พอ'));return;}if(E.d.crystals+q*1000>E.crystalCapacity()){toast(tr('พื้นที่คลังผลึกไม่พอ'));return;}crystalPurchaseQuantity=q;warRequest('test_claim');};
Game.crystalCenter=function(){E.sync();var online=!!E.d.onlineCrystal;open(tr('<h2>🔮 ศูนย์ผลึกโนวา</h2><button class="wide green" onclick="Game.crystalExchange()">💎 แลกเพชรเป็นผลึก</button><p>')+Math.floor(E.d.crystals)+' / '+E.crystalCapacity()+tr(' ผลึก • ')+E.crystalRate()+tr(' / ชั่วโมง<br>')+ (online?tr('ใช้ผลึกอัปเกรดจากปุ่มที่อาคารได้เลย'):tr('สร้างโรงสังเคราะห์ผลึกเมื่อฐานหลัก Lv.3<br>ผลผลิตเข้าคลังอัตโนมัติแม้ปิดเกม'))+tr('</p><p>ผลึกใช้ผลิตเครื่องบินทิ้งระเบิด พลพลาสมา รถถังพลาสมา หุ่นหนัก และอัปเกรดอาคาร Lv.6–15</p>')+[['weapon',tr('กระสุนเจาะเกราะ • พลังโจมตี +10% / ขั้น')],['armor',tr('เกราะพิเศษ • HP +10% / ขั้น')]].map(function(a){return'<button class="wide" onclick="Game.research(\''+a[0]+'\')">'+a[1]+'<br>Lv.'+E.d.research[a[0]]+'/5 • '+(50*(E.d.research[a[0]]+1))+tr(' ผลึก</button>');}).join('')+tr('<button class="wide" onclick="Game.training()">ผลิตอาวุธหนัก</button><button class="wide" onclick="Game.war()">รีเฟรช / จัดการผลึกออนไลน์</button><button class="wide" onclick="Game.build()">สร้างโรงผลิตและคลัง</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.research=function(kind){if(E.d.onlineCrystal&&upgradeJob225('research:'+kind)){toast(tr('กำลังวิจัย รอเวลาให้ครบ'));return;}if(E.d.onlineCrystal){warRequest('research',{kind:kind,economyVersion:2,request_id:nonce160()});return;}toast(E.buyResearch(kind)||tr('เริ่มวิจัยแล้ว'));Game.crystalCenter();};
function syncCrystal(d){if(!d||!d.enrolled)return;
 if(d.resources){
  E.sync();var ack=E.d.raidDeltas||{owner:d.owner,gold_delta:0,power_delta:0};
  if(ack.owner!==d.owner){toast(tr('กรุณาใช้บัญชีเดิมสำหรับฐานนี้'));return;}
  var previous=JSON.stringify(E.d);
  E.d.gold=Math.max(0,Math.min(E.resourceCapacity(),E.d.gold+d.resources.gold_delta-ack.gold_delta));
  E.d.power=Math.max(0,Math.min(E.resourceCapacity('power'),E.d.power+d.resources.power_delta-ack.power_delta));
  E.d.raidDeltas={owner:d.owner,gold_delta:d.resources.gold_delta,power_delta:d.resources.power_delta};
  E.d.resourceSeq=Math.max(E.d.resourceSeq||0,d.resources.seq||0);
  if(!E.save()){E.d=JSON.parse(previous);return;}
 }
E.d.crystals=0;E.d.onlineCrystal={owner:d.owner,capacity:d.capacity,rate:d.rate||0};if(d.research)E.d.research=d.research;if(d.infra)E.d.buildings.forEach(function(b){if(d.infra[b.type]&&active(b))b.lv=Math.max(b.lv,d.infra[b.type]);});E.d.buildings.filter(function(b){return b.type==='crystalplant';}).forEach(function(b){b.collected=E.now();});E.save();hud();}
var infrastructureAfterPublish=null;
Game.onlineBaseUpgrade=function(kind){if(!E.builderFree()){toast(tr('โดรนช่างกำลังทำงานครบทุกตัว'));return;}var b=E.d.buildings.find(function(b){return b.type===kind;});if(!b||b.until){toast(tr('รอการก่อสร้างให้เสร็จก่อน'));return;}if(b.lv>=E.hq()||b.lv>=MAX_BUILDING_LEVEL){toast(tr('อัปเกรดศูนย์บัญชาการก่อน'));return;}if(E.d.crystals<200*b.lv*b.lv){toast(tr('ต้องใช้ ')+200*b.lv*b.lv+tr(' ผลึก'));return;}if(kind==='garrison'&&warState&&b.lv>=warState.tier){open(tr('<h2>อัปเกรดอาคาร</h2><p>ต้องยกระดับกองกำลังออนไลน์ก่อน</p><button class="wide green" onclick="Game.warUpgrade()">ยกระดับกองกำลัง</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(warBusy)return;if(E.d.pendingWar){Game.retryOnline();return;}infrastructureAfterPublish=kind;Game.warPublish(false);};
Game.onlineForge=function(i){warRequest('forge',{kind:i,request_id:nonce160()});};
Game.onlineStation=function(i,delta){warRequest('station',{kind:i,delta:delta,request_id:nonce160()});};
function onlineArsenal(){var d=warState;if(!d||!d.enrolled){Game.war();return;}var costs=[2,8,6,6,10,16,20,20,15,30,45];open(tr('<h2>คลังแสงและป้องกันออนไลน์</h2><p>🔮 ')+d.crystals+tr(' • ประจำการ ')+spaces(d.garrison||U.map(function(){return 0;}))+' / '+(5+5*(d.infra?d.infra.garrison:1))+tr('<br>ฝึกกองกำลังด้วยผลึกบนเซิร์ฟเวอร์ • แยกจากกองทัพฝึกซ้อมในเครื่อง<br>กองกำลังยังอยู่ครบหลังจบการบุก</p>')+U.map(function(u,i){return'<div class="def-row"><b>'+u.name+tr('</b><small>ว่าง ')+((d.inventory||[])[i]||0)+tr(' • ป้องกัน ')+((d.garrison||[])[i]||0)+'</small><button onclick="Game.onlineForge('+i+tr(')">ฝึก ')+costs[i]+' 🔮</button><button onclick="Game.onlineStation('+i+tr(',1)">+ ป้องกัน</button><button onclick="Game.onlineStation(')+i+tr(',-1)">− ถอน</button></div>');}).join('')+tr('<button class="wide" onclick="Game.war()">กลับ</button>'));}
Game.onlineArsenal=onlineArsenal;
function requestCrystal(kind,index){if(E.d.pendingCrystal){Game.retryCrystal();return;}var b=E.d.buildings.find(function(b){return b.id===index;}),u=U[index],c=kind==='unit'?{gold:0,power:u.cost}:b?E.upgradeCost(b):null;if(!c)return;if(E.d.crystals<(kind==='unit'?u.crystals:c.crystals)){toast(tr('ผลึกไม่พอ'));return;}if(kind==='unit'){var lock=E.unitLock(index);if(lock||E.housing()+u.space>E.capacity()){toast(lock||tr('ค่ายทหารเต็ม'));return;}}else if(b.until||b.lv>=MAX_BUILDING_LEVEL||b.type!=='hq'&&b.lv>=E.hq()||!E.builderFree()){toast(tr('อาคารยังอัปเกรดไม่ได้ / โดรนช่างไม่ว่าง'));return;}if(E.d.gold<c.gold||E.d.power<c.power){toast(tr('ทองหรือพลังงานไม่พอ'));return;}E.d.gold-=c.gold;E.d.power-=c.power;E.d.pendingCrystal={owner:E.d.onlineCrystal.owner,kind:kind,index:index,economyVersion:2,level:kind==='upgrade'?b.lv:null,request_id:nonce160(),gold:c.gold,power:c.power};if(!E.save()){E.d.gold+=c.gold;E.d.power+=c.power;delete E.d.pendingCrystal;toast(tr('บันทึกไม่ได้ กรุณาตรวจพื้นที่ว่าง'));return;}Game.retryCrystal();}
Game.retryCrystal=function(){if(!warState||!warState.owner){resumeCrystal=true;warRequest('status');return;}if(E.d.pendingCrystal&&E.d.pendingCrystal.owner!==warState.owner){toast(tr('กรุณาใช้บัญชีเดิมที่เริ่มรายการผลึก'));return;}if(E.d.pendingCrystal)warRequest('fund',E.d.pendingCrystal);};
function finishCrystal(receipt){var p=E.d.pendingCrystal;if(!p||!receipt||receipt.id!==p.request_id||E.d.receipts.includes(receipt.id))return;if(receipt.cancelled){E.d.gold+=p.gold||0;E.d.power+=p.power||0;delete E.d.pendingCrystal;E.save();return;}if(receipt.kind==='walls'){p.items.forEach(function(a){var b=E.d.buildings.find(function(b){return b.id===a.id;});if(b&&b.lv===a.level&&!b.until){b.builderBatch228=p.request_id;b.started=E.now();b.until=b.started+E.upgradeCost(b).time*1000;}});}else if(receipt.kind==='sell_crystals'){E.d.gems+=receipt.gems;}else if(receipt.kind==='unit'){E.d.queue.push({kind:p.index,started:E.now(),until:E.now()+U[p.index].time*1000});}else{var b=E.d.buildings.find(function(b){return b.id===p.index;});if(b&&b.lv===p.level&&!b.until){b.started=E.now();b.until=E.now()+E.upgradeCost(b).time*1000;}}
 E.d.receipts.push(receipt.id);E.d.receipts=E.d.receipts.slice(-100);delete E.d.pendingCrystal;E.save();hud();toast(tr('เริ่มงานแล้ว'));}
var wallApply160=Game.wallApply;Game.wallApply=function(){if(!wallPending)return;var q=E.wallQuote(wallPending.id,wallPending.mode);if(!E.d.onlineCrystal||!q.crystals){wallApply160();return;}if(E.d.pendingCrystal){Game.retryCrystal();return;}if(JSON.stringify(q)!==wallPending.quote||E.d.gold<q.gold||E.d.power<q.power||E.d.crystals<q.crystals){toast(tr('ทรัพยากรไม่พอหรือรายการเปลี่ยน'));return;}var items=q.ids.map(function(id){var b=E.d.buildings.find(function(b){return b.id===id;});return{id:id,level:b.lv};});E.d.gold-=q.gold;E.d.power-=q.power;E.d.pendingCrystal={owner:E.d.onlineCrystal.owner,kind:'walls',economyVersion:2,items:items,gold:q.gold,power:q.power,request_id:nonce160()};E.save();wallPending=null;Game.retryCrystal();};
var baseTrain160=Game.train;Game.train=function(i){if(U[i].crystals&&E.d.onlineCrystal){requestCrystal('unit',i);return;}baseTrain160(i);};
var baseUpgrade160=Game.upgrade;Game.upgrade=function(){var b=E.d.buildings.find(function(b){return b.id===selected;});if(b&&b.type!=='hq'&&b.lv>=E.hq()){toast(tr('อัปเกรดศูนย์บัญชาการก่อน'));return;}if(b&&false){Game.onlineBaseUpgrade(b.type);return;}if(b&&E.d.onlineCrystal&&b.type!=='wall'&&E.upgradeCost(b).crystals>0){requestCrystal('upgrade',b.id);return;}baseUpgrade160();};

var warRequest160=warRequest;warRequest=function(action,payload){if(warBusy)return;var mutations=['infrastructure','forge','station','research'];if(mutations.includes(action)&&!(payload&&(payload.resource233||payload.admob230))){if(E.d.pendingWar&&E.d.pendingWar.payload.request_id!==payload.request_id){Game.retryOnline();return;}if(!E.d.pendingWar){E.d.pendingWar={action:action,payload:payload,owner:warState&&warState.owner};E.save();}}warRequest160(action,payload);};
Game.retryOnline=function(){var p=E.d.pendingWar;if(!p)return;if(!warState||!warState.owner){resumeCrystal=true;warRequest('status');return;}if(p.owner!==warState.owner){toast(tr('กรุณาเข้าสู่ระบบบัญชีเดิม'));return;}warRequest(p.action,p.payload);};
Game.cancelOnline=function(){var owner=E.d.pendingCrystal?E.d.pendingCrystal.owner:E.d.pendingWar&&E.d.pendingWar.owner;var p=E.d.pendingCrystal||E.d.pendingWar&&E.d.pendingWar.payload;if(!p)return;if(!warState||owner!==warState.owner){toast(tr('ต้องเข้าสู่ระบบบัญชีที่เริ่มรายการ'));return;}warRequest('cancel',{request_id:p.request_id});};

// Test wallet is server-owned and deliberately separate from offline/advertising gems.
var testWallet=null,testTarget=null;
Game.legacyGems=function(){warRequest('test_status');};
Game.testShop=treasury;
Game.promoClaim=function(){var n=E.claimPromo();toast(n>0?tr('รับ 10,000 เพชรแล้ว'):n<0?tr('บันทึกไม่ได้ กรุณาลองอีกครั้ง'):tr('รับโปรโมชั่นวันนี้แล้ว'));hud();treasury();};
Game.testClaim=Game.promoClaim;
function testShop(){var w=testWallet;if(!w)return;open(tr('<h2>💎 กระเป๋าเดิม</h2><p>มี ')+w.test_gems.toLocaleString()+tr(' เพชร</p>') +[['gold',tr('5,000 ทอง')],['power',tr('5,000 พลังงาน')]].map(function(a){return '<button class="wide" onclick="Game.testQuote(\''+a[0]+'\')">10 💎 → '+a[1]+'</button>';}).join('')+(E.d.pendingTest?tr('<button class="wide" onclick="Game.retryTest()">ตรวจรายการแลกที่ค้าง</button><button class="wide" onclick="Game.cancelTest()">ยกเลิกรายการที่ยังไม่สำเร็จ</button>'):'')+tr('<button class="wide" onclick="Game.resources()">รับทอง / พลังงานที่แลกไว้เข้าคลัง</button><button class="wide" onclick="Game.war()">เข้าร่วม / รีเฟรชฐานออนไลน์</button><button class="wide" onclick="Game.close()">กลับ</button>'));}
Game.testQuote=function(kind){if(E.d.pendingTest){Game.retryTest();return;}var label={gold:tr('ทอง'),power:tr('พลังงาน'),crystals:tr('ผลึก')}[kind];if(!label)return;open(tr('<h2>แลก')+label+tr('</h2><p>ใช้เพชรจากกระเป๋าเดิม • เลือกจำนวนชุด<br>หากคลังในเครื่องเต็ม จะเก็บส่วนที่เหลือไว้ให้รับภายหลัง</p>')+[1,10,100].map(function(q){return '<button class="wide" onclick="Game.testExchange(\''+kind+'\','+q+')">'+(q*10)+' 💎 → '+(q*(kind==='crystals'?1000:5000))+' '+label+'</button>';}).join('')+tr('<button class="wide" onclick="Game.testShop()">กลับ</button>'));};
Game.testExchange=function(kind,quantity){if(!testWallet||warBusy||E.d.pendingTest)return;E.d.pendingTest={owner:testWallet.owner,kind:kind,quantity:quantity,rateVersion:2,request_id:nonce160()};if(!E.save()){delete E.d.pendingTest;toast(tr('บันทึกไม่ได้ กรุณาตรวจพื้นที่เครื่อง'));return;}Game.retryTest();};
Game.cancelTest=function(){var p=E.d.pendingTest;if(p&&testWallet&&p.owner===testWallet.owner)warRequest('test_cancel',{request_id:p.request_id});};
Game.retryTest=function(){var p=E.d.pendingTest;if(!p)return;if(!testWallet||p.owner!==testWallet.owner){toast(tr('เข้าสู่ระบบบัญชีที่เริ่มรายการแลกก่อน'));return;}warRequest('test_exchange',p);};
function testEvent(action,d){testWallet=d;if(action==='test_claim'&&crystalPurchaseQuantity){var q=crystalPurchaseQuantity;crystalPurchaseQuantity=0;if(!E.d.onlineCrystal||d.owner!==E.d.onlineCrystal.owner){toast(tr('กรุณาใช้บัญชีเดียวกับคลังผลึก'));return;}if(E.d.gems<q*10||d.test_gems<q*10){toast(tr('เพชรสำหรับแลกไม่พอ'));return;}var beforeGems=E.d.gems;E.d.gems-=q*10;E.d.pendingTest={owner:d.owner,kind:'crystals',quantity:q,request_id:nonce160(),gemDebit:q*10,rateVersion:2};if(!E.save()){E.d.gems=beforeGems;delete E.d.pendingTest;toast(tr('บันทึกไม่ได้ กรุณาลองอีกครั้ง'));return;}Game.retryTest();return;}if(d.online)syncCrystal(d.online);var p=E.d.pendingTest,r=d.receipt;if((action==='test_exchange'||action==='test_cancel')&&p&&r&&r.id===p.request_id&&p.owner===d.owner){var before=JSON.stringify(E.d);E.d.testReceipts=E.d.testReceipts||[];if(!E.d.testReceipts.includes(r.id)){if(r.cancelled&&p.gemDebit)E.d.gems+=p.gemDebit;if(!r.cancelled&&(r.kind==='gold'||r.kind==='power')){E.d.testDelivery=E.d.testDelivery||{gold:0,power:0};E.d.testDelivery[r.kind]+=r.amount;E.d.testDelivery[r.kind]-=E.deposit(r.kind,E.d.testDelivery[r.kind]);}E.d.testReceipts.push(r.id);}delete E.d.pendingTest;if(!E.save()){E.d=JSON.parse(before);toast(tr('บันทึกไม่ได้ รายการยังรอตรวจซ้ำ'));}else toast(r.cancelled?tr('ยกเลิกรายการที่ยังไม่สำเร็จแล้ว'):tr('แลกทรัพยากรสำเร็จ'));}
 if(action==='test_targets'){testTarget=d.target;Game.practicePreview();return;}if(p&&p.gemDebit){Game.crystalExchange();hud();return;}testShop();hud();if(action==='test_claim')toast(tr('ยืนยันรางวัลวันนี้แล้ว • เพชรคงเหลือ ')+d.test_gems.toLocaleString()+tr(' เม็ด'));}
Game.practicePreview=function(){if(!testTarget)return;open('<h2>'+escapeHTML(testTarget.callsign)+'</h2><p>'+(testTarget.bot?tr('ฐานทดสอบที่ระบบเตรียมให้'):tr('สนามซ้อมจากผังฐานผู้เล่นจริง'))+tr('<br>แตะขอบสีฟ้าเพื่อวางทหารและชมการต่อสู้<br>มีกองทัพทดสอบให้ • บุกซ้ำได้ • ไม่ชิงทรัพยากร<br>ช่วงทดสอบไม่จำกัดระดับหรือโล่</p><button class="wide green" onclick="Game.practiceStart()">เข้าสนามและโจมตีเอง</button><button class="wide" onclick="Game.warTargets()">สุ่มฐานอื่น</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.practiceStart=function(){if(!E.scoutPlayer(testTarget)){toast(tr('ผังฐานไม่สมบูรณ์ ลองสุ่มใหม่'));return;}screen='raid';paused=false;selected=null;placing=moving=null;deployKind=0;zoom=.85;panX=0;panY=-110;close();hud();};
Game.practiceAgain=function(){home();Game.warTargets();};
var resourceMenu170=Game.resources;Game.resources=function(){resourceMenu170();var d=E.d.testDelivery;if(d&&(d.gold||d.power))open(tr('<h2>ทรัพยากรที่แลกไว้</h2><p>รอเข้าคลัง: ')+d.gold+tr(' ทอง / ')+d.power+tr(' พลังงาน<br>รับได้ตามพื้นที่ว่าง ส่วนเกินจะเก็บไว้</p><button class="wide green" onclick="Game.receiveTestResources()">รับเข้าคลัง</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.receiveTestResources=function(){var d=E.d.testDelivery;if(d){E.sync();d.gold-=E.deposit('gold',d.gold);d.power-=E.deposit('power',d.power);E.save();}Game.resources();hud();};

function coordinates(e){var r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*420/r.width,y:(e.clientY-r.top)*viewHeight/r.height};}
// Move preview never mutates the saved layout until the green confirmation.
var movePreview224=null;
function previewBuilding224(b){return screen==='home'&&moving===b.id&&movePreview224&&movePreview224.id===b.id?Object.assign({},b,{x:movePreview224.x,y:movePreview224.y}):b;}
function pickBuilding224(p){var best=null,d=Infinity;E.d.buildings.forEach(function(b){var q=point(previewBuilding224(b).x,previewBuilding224(b).y),dd=Math.hypot(p.x-q.x,p.y-(q.y-13*zoom));if(dd<Math.max(20,30*zoom)&&dd<d){d=dd;best=b;}});return best;}
function beginMove224(b){if(!b)return;if(E.d.siegeLocked){toast(tr('ฐานกำลังถูกโจมตี รอการรบสิ้นสุด'));return;}selected=b.id;moving=b.id;placing=null;movePreview224={id:b.id,x:b.x,y:b.y};hud();}
